import { useMemo, useRef } from 'react'
import { useFrame } from '@react-three/fiber'
import * as THREE from 'three'

/** Small, fast, deterministic PRNG (mulberry32). */
function mulberry32(seed) {
  let a = seed >>> 0
  return function () {
    a |= 0
    a = (a + 0x6d2b79f5) | 0
    let t = Math.imul(a ^ (a >>> 15), 1 | a)
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296
  }
}

/**
 * Seeded unit-direction velocities: one unit vector per particle,
 * rejection-sampled uniformly on the sphere.
 */
function makeVelocities(count, seed) {
  const rand = mulberry32(seed)
  const velocities = new Float32Array(count * 3)
  for (let i = 0; i < count; i++) {
    let x, y, z, len
    do {
      x = rand() * 2 - 1
      y = rand() * 2 - 1
      z = rand() * 2 - 1
      len = x * x + y * y + z * z
    } while (len === 0 || len > 1)
    len = Math.sqrt(len)
    velocities[i * 3] = x / len
    velocities[i * 3 + 1] = y / len
    velocities[i * 3 + 2] = z / len
  }
  return velocities
}

/**
 * Starburst particle system.
 *
 * Renders a <points> whose BufferGeometry holds:
 *  - `position`: all particles starting at the origin
 *  - `userData.velocities`: seeded unit direction per particle (speed 1)
 *
 * Every frame each point moves outward along its velocity by delta seconds.
 *
 * @param {{count?: number, seed?: number}} props
 */
export function Starburst({ count = 100, seed = 1 }) {
  const geomRef = useRef(null)

  // Deterministic velocities for the given seed; recreated when count/seed change.
  const velocities = useMemo(() => makeVelocities(count, seed), [count, seed])

  // All particles start at the origin.
  const positions = useMemo(() => new Float32Array(count * 3), [count])

  useFrame((_, delta) => {
    const geometry = geomRef.current
    if (!geometry) return
    const attr = geometry.attributes.position
    const arr = attr.array
    for (let i = 0; i < arr.length; i++) {
      arr[i] += velocities[i] * delta
    }
    attr.needsUpdate = true
  })

  return (
    <points>
      <bufferGeometry ref={geomRef} userData={{ velocities }}>
        <bufferAttribute attach="attributes-position" args={[positions, 3]} />
      </bufferGeometry>
      <pointsMaterial size={0.05} />
    </points>
  )
}

export default Starburst

