import { describe, it, expect } from 'vitest'
import * as THREE from 'three'
import ReactThreeTestRenderer from '@react-three/test-renderer'
import { Starburst } from '../src/Starburst.jsx'

async function mount(count, seed) {
  return ReactThreeTestRenderer.create(<Starburst count={count} seed={seed} />)
}

function getPoints(renderer) {
  return renderer.scene.findByType('points').instance
}

describe('Starburst', () => {
  it('renders a <points> with a position attribute of exactly `count` vertices', async () => {
    const renderer = await mount(50, 3)
    const points = getPoints(renderer)
    expect(points).toBeInstanceOf(THREE.Points)
    const attr = points.geometry.attributes.position
    expect(attr.count).toBe(50)
    await renderer.unmount()
  })

  it('starts every particle at the origin and bakes seeded unit velocities into userData', async () => {
    const renderer = await mount(50, 3)
    const points = getPoints(renderer)
    const attr = points.geometry.attributes.position

    for (let i = 0; i < attr.count; i++) {
      expect(attr.getX(i)).toBe(0)
      expect(attr.getY(i)).toBe(0)
      expect(attr.getZ(i)).toBe(0)
    }

    const velocities = points.geometry.userData.velocities
    expect(velocities).toBeInstanceOf(Float32Array)
    expect(velocities.length).toBe(50 * 3)
    for (let i = 0; i < 50; i++) {
      const x = velocities[i * 3]
      const y = velocities[i * 3 + 1]
      const z = velocities[i * 3 + 2]
      expect(Math.hypot(x, y, z)).toBeCloseTo(1, 6)
    }
    await renderer.unmount()
  })

  it('after 30 frames at 1/60s each particle sits 0.5 units out along an unchanged direction', async () => {
    const renderer = await mount(50, 3)
    const points = getPoints(renderer)

    await renderer.advanceFrames(30, 1 / 60)

    const attr = points.geometry.attributes.position
    const velocities = points.geometry.userData.velocities
    const dir = new THREE.Vector3()

    for (let i = 0; i < attr.count; i++) {
      const px = attr.getX(i)
      const py = attr.getY(i)
      const pz = attr.getZ(i)

      // Unit speed * half a second => distance 0.5.
      expect(Math.hypot(px, py, pz)).toBeCloseTo(0.5, 3)

      // Direction of travel must equal the baked velocity exactly.
      dir.set(px, py, pz).normalize()
      const vx = velocities[i * 3]
      const vy = velocities[i * 3 + 1]
      const vz = velocities[i * 3 + 2]
      expect(dir.x).toBeCloseTo(vx, 6)
      expect(dir.y).toBeCloseTo(vy, 6)
      expect(dir.z).toBeCloseTo(vz, 6)
    }
    await renderer.unmount()
  })

  it('remounting with the same seed reproduces identical velocities', async () => {
    const first = await mount(50, 3)
    const second = await mount(50, 3)

    const v1 = getPoints(first).geometry.userData.velocities
    const v2 = getPoints(second).geometry.userData.velocities

    expect(Array.from(v1)).toEqual(Array.from(v2))

    // A different seed yields different velocities.
    const third = await mount(50, 7)
    const v3 = getPoints(third).geometry.userData.velocities
    expect(Array.from(v1)).not.toEqual(Array.from(v3))

    await Promise.all([first.unmount(), second.unmount(), third.unmount()])
  })

  it('resizes the position attribute when the count prop changes', async () => {
    const renderer = await mount(50, 3)
    expect(getPoints(renderer).geometry.attributes.position.count).toBe(50)

    await renderer.update(<Starburst count={120} seed={3} />)

    const points = getPoints(renderer)
    const attr = points.geometry.attributes.position
    expect(attr.count).toBe(120)
    expect(points.geometry.userData.velocities.length).toBe(120 * 3)

    // Resized particles still start at the origin.
    let allZero = true
    for (let i = 0; i < attr.count; i++) {
      if (attr.getX(i) !== 0 || attr.getY(i) !== 0 || attr.getZ(i) !== 0) {
        allZero = false
        break
      }
    }
    expect(allZero).toBe(true)

    await renderer.unmount()
  })
})

