  const a = await R.create(<Starburst count={50} seed={3} />)
  const b = await R.create(<Starburst count={50} seed={3} />)
  await Promise.all([a.unmount(), b.unmount()])
  const r = await R.create(<Starburst count={50} seed={3} />)
  await r.update(<Starburst count={120} seed={3} />)
  console.error('B:', await types(r))
})
